namespace sv_67bcdecc65cc4587a1f446d9f581e589.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

@namespace sv_67bcdecc65cc4587a1f446d9f581e589.Components.Pages.Apply

<nav class="step-indicator" aria-label="Application progress">
    <ol class="step-list">
        @for (int i = 0; i < StepNames.Count; i++)
        {
            var stepIndex = i;
            var status = GetStepStatus(stepIndex);
            <li class="step-item @status" @onclick="() => HandleStepClick(stepIndex)"
                role="button" tabindex="@(status == "completed" ? 0 : -1)"
                aria-current="@(status == "active" ? "step" : null)">
                <span class="step-circle">
                    @if (status == "completed")
                    {
                        <span class="checkmark">✓</span>
                    }
                    else
                    {
                        @(stepIndex + 1)
                    }
                </span>
                <span class="step-label">@StepNames[stepIndex]</span>
            </li>
        }
    </ol>
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public IReadOnlyList<string> StepNames { get; set; } = [];
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }

    private static readonly List<string> DefaultStepNames = ["Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"];

    private string GetStepStatus(int index)
    {
        if (index == CurrentStep) return "active";
        if (index < CurrentStep) return "completed";
        return "future";
    }

    private async Task HandleStepClick(int index)
    {
        if (index < CurrentStep)
        {
            await OnStepClicked.InvokeAsync(index);
        }
    }
}

@namespace sv_67bcdecc65cc4587a1f446d9f581e589.Components.Pages.Apply

<fieldset class="work-entry-form">
    <legend>Position @(Index + 1)</legend>

    <div class="form-group">
        <label for="company-@Index">Company Name *</label>
        <input id="company-@Index" type="text" value="@Entry.Company"
               @onchange="e => UpdateField(e, (v, entry) => entry with { Company = v })" required />
    </div>

    <div class="form-group">
        <label for="title-@Index">Job Title *</label>
        <input id="title-@Index" type="text" value="@Entry.Title"
               @onchange="e => UpdateField(e, (v, entry) => entry with { Title = v })" required />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label for="start-@Index">Start Date *</label>
            <input id="start-@Index" type="date" value="@Entry.StartDate.ToString("yyyy-MM-dd")"
                   @onchange="e => UpdateDate(e, true)" required />
        </div>

        <div class="form-group">
            <label for="end-@Index">End Date</label>
            <input id="end-@Index" type="date" value="@Entry.EndDate?.ToString("yyyy-MM-dd")"
                   @onchange="e => UpdateDate(e, false)" disabled="@IsCurrent" />
        </div>

        <div class="form-group form-group-checkbox">
            <label>
                <input type="checkbox" checked="@IsCurrent" @onchange="HandleCurrentToggle" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label for="desc-@Index">Description</label>
        <textarea id="desc-@Index" rows="3" value="@Entry.Description"
                  @onchange="e => UpdateField(e, (v, entry) => entry with { Description = v })"></textarea>
    </div>

    @if (CanRemove)
    {
        <button type="button" class="btn btn-danger btn-sm" @onclick="OnRemove">Remove</button>
    }
</fieldset>

@code {
    [Parameter, EditorRequired] public WorkEntry Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<WorkEntry> OnChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.EndDate is null && Entry.StartDate != default;

    private async Task UpdateField(ChangeEventArgs e, Func<string, WorkEntry, WorkEntry> updater)
    {
        var value = e.Value?.ToString() ?? "";
        await OnChanged.InvokeAsync(updater(value, Entry));
    }

    private async Task UpdateDate(ChangeEventArgs e, bool isStart)
    {
        if (DateTime.TryParse(e.Value?.ToString(), out var date))
        {
            var updated = isStart
                ? Entry with { StartDate = date }
                : Entry with { EndDate = date };
            await OnChanged.InvokeAsync(updated);
        }
    }

    private async Task HandleCurrentToggle(ChangeEventArgs e)
    {
        var isCurrent = (bool)(e.Value ?? false);
        var updated = Entry with { EndDate = isCurrent ? null : DateTime.Today };
        await OnChanged.InvokeAsync(updated);
    }
}

