            </div>
            @if (References is not null)
            {
                @foreach (var r in References)
                {
                    <div class="review-entry">
                        <strong>@r.Name</strong> — @r.Relationship
                        <br />
                        <span class="text-muted">@r.Email @(!string.IsNullOrEmpty(r.Phone) ? $"| {r.Phone}" : "")</span>
                    </div>
                }
            }
        </section>

        <section class="review-section">
            <div class="review-header">
                <h3>Cover Letter</h3>
                <button type="button" class="btn-link" @onclick="() => OnEditSection.InvokeAsync(3)">Edit</button>
            </div>
            <p class="cover-letter-preview">@CoverLetter</p>
        </section>

        <div class="step-actions">
            <button type="button" class="btn btn-outline" @onclick="OnBack">Back</button>
            <button type="button" class="btn btn-primary btn-submit" @onclick="HandleSubmit" disabled="@IsSubmitting">
                @(IsSubmitting ? "Submitting..." : "Submit Application")
            </button>
        </div>
    }
</div>

@code {
    [Parameter] public PersonalInfo? Personal { get; set; }
    [Parameter] public WorkHistory? Work { get; set; }
    [Parameter] public List<Reference>? References { get; set; }
    [Parameter] public string? CoverLetter { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback<int> OnEditSection { get; set; }
    [Parameter, EditorRequired] public IApplicationService ApplicationService { get; set; } = default!;

    private bool IsSubmitting { get; set; }
    private bool IsSubmitted { get; set; }
    private int ApplicationId { get; set; }
    private string? ErrorMessage { get; set; }

    private async Task HandleSubmit()
    {
        if (Personal is null || Work is null || References is null || string.IsNullOrEmpty(CoverLetter))
        {
            ErrorMessage = "Application data is incomplete. Please go back and fill in all sections.";
            return;
        }

        IsSubmitting = true;
        ErrorMessage = null;

        try
        {
            var application = new JobApplication(Personal, Work, References, CoverLetter);
            ApplicationId = await ApplicationService.SubmitApplicationAsync(application);
            IsSubmitted = true;
        }
        catch (Exception ex)
        {
            ErrorMessage = $"Submission failed: {ex.Message}. Please try again.";
        }
        finally
        {
            IsSubmitting = false;
        }
    }
}

