@namespace sv_67bcdecc65cc4587a1f446d9f581e589.Components.Pages.Apply

<div class="step-content">
    <h2>Cover Letter</h2>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-danger">@ErrorMessage</div>
    }

    <div class="form-group">
        <label for="cover-letter">Write your cover letter below</label>
        <textarea id="cover-letter" rows="12" maxlength="@MaxLength"
                  @bind="CoverLetterText" @bind:event="oninput"
                  placeholder="Tell us why you're a great fit for this role..."></textarea>
        <span class="char-count @(CoverLetterText.Length > MaxLength ? "over-limit" : "")">
            @CoverLetterText.Length / @MaxLength characters
        </span>
    </div>

    <div class="step-actions">
        <button type="button" class="btn btn-outline" @onclick="OnBack">Back</button>
        <button type="button" class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    private const int MaxLength = 2000;

    [Parameter] public string? InitialText { get; set; }
    [Parameter] public EventCallback<string> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string CoverLetterText { get; set; } = "";
    private string? ErrorMessage { get; set; }

    protected override void OnParametersSet()
    {
        if (InitialText is not null)
        {
            CoverLetterText = InitialText;
        }
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        if (string.IsNullOrWhiteSpace(CoverLetterText))
        {
            ErrorMessage = "Please write a cover letter before continuing.";
            return;
        }

        if (CoverLetterText.Length > MaxLength)
        {
            ErrorMessage = $"Cover letter must be {MaxLength} characters or fewer.";
            return;
        }

        await OnNext.InvokeAsync(CoverLetterText);
    }
}

