namespace sv_67bcdecc65cc4587a1f446d9f581e589.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

@page "/apply"
@rendermode InteractiveServer
@namespace sv_67bcdecc65cc4587a1f446d9f581e589.Components.Pages.Apply
@using sv_67bcdecc65cc4587a1f446d9f581e589.Models
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-wizard">
    <StepIndicator CurrentStep="@currentStep" StepNames="@stepNames" OnStepClicked="GoToStep" />

    <div class="wizard-body">
        @switch (currentStep)
        {
            case 0:
                <PersonalInfoStep Info="@personalInfo"
                                  ApplicationService="@ApplicationService"
                                  OnNext="HandlePersonalNext" />
                break;
            case 1:
                <WorkHistoryStep History="@workHistory"
                                 OnNext="HandleWorkNext"
                                 OnBack="GoBack" />
                break;
            case 2:
                <ReferencesStep InitialReferences="@references"
                                OnNext="HandleReferencesNext"
                                OnBack="GoBack" />
                break;
            case 3:
                <CoverLetterStep InitialText="@coverLetter"
                                 OnNext="HandleCoverLetterNext"
                                 OnBack="GoBack" />
                break;
            case 4:
                <ReviewStep Personal="@personalInfo"
                            Work="@workHistory"
                            References="@references"
                            CoverLetter="@coverLetter"
                            ApplicationService="@ApplicationService"
                            OnBack="GoBack"
                            OnEditSection="GoToStep" />
                break;
        }
    </div>
</div>

@code {
    private static readonly List<string> stepNames = ["Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"];

    private int currentStep;
    private PersonalInfo? personalInfo;
    private WorkHistory? workHistory;
    private List<Reference>? references;
    private string? coverLetter;

    private void GoToStep(int step)
    {
        if (step >= 0 && step <= 4)
        {
            currentStep = step;
        }
    }

    private void GoBack()
    {
        if (currentStep > 0) currentStep--;
    }

    private void HandlePersonalNext(PersonalInfo info)
    {
        personalInfo = info;
        currentStep = 1;
    }

    private void HandleWorkNext(WorkHistory history)
    {
        workHistory = history;
        currentStep = 2;
    }

    private void HandleReferencesNext(List<Reference> refs)
    {
        references = refs;
        currentStep = 3;
    }

    private void HandleCoverLetterNext(string text)
    {
        coverLetter = text;
        currentStep = 4;
    }
}

.application-wizard {
    max-width: 800px;
    margin: 2rem auto;
    padding: 0 1rem;
}

/* Step Indicator */
.step-list {
    display: flex;
    list-style: none;
    padding: 0;
    margin: 0 0 2rem 0;
    justify-content: space-between;
}

.step-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    flex: 1;
    position: relative;
    cursor: default;
}

.step-item.completed {
    cursor: pointer;
}

.step-item::after {
    content: '';
    position: absolute;
    top: 16px;
    left: 50%;
    width: 100%;
    height: 2px;
    background: #e0e0e0;
    z-index: 0;
}

.step-item:last-child::after {
    display: none;
}

.step-item.completed::after {
    background: #4caf50;
}

.step-item.active::after {
    background: #e0e0e0;
}

.step-circle {
    width: 32px;
    height: 32px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.85rem;
    font-weight: 600;
    z-index: 1;
    background: #e0e0e0;
    color: #999;
    transition: all 0.2s;
}

.step-item.active .step-circle {
    background: #1976d2;
    color: #fff;
}

.step-item.completed .step-circle {
    background: #4caf50;
    color: #fff;
}

.step-label {
    margin-top: 0.5rem;
    font-size: 0.75rem;
    text-align: center;
    color: #999;
}

.step-item.active .step-label {
    color: #1976d2;
    font-weight: 600;
}

.step-item.completed .step-label {
    color: #4caf50;
}

.checkmark {
    font-size: 1rem;
}

/* Wizard body */
.wizard-body {
    background: #fff;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 2rem;
}

.step-content h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    color: #333;
}

/* Forms */
.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.35rem;
    font-weight: 500;
    font-size: 0.9rem;
    color: #444;
}

.form-group input,
.form-group textarea,
.form-group select {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 0.95rem;
    box-sizing: border-box;
}

.form-group input:focus,
.form-group textarea:focus {
    outline: none;
    border-color: #1976d2;
    box-shadow: 0 0 0 2px rgba(25, 118, 210, 0.15);
}

.form-row {
    display: flex;
    gap: 1rem;
    flex-wrap: wrap;
}

.form-row .form-group {
    flex: 1;
    min-width: 150px;
}

.form-group-checkbox {
    display: flex;
    align-items: flex-end;
    padding-bottom: 0.5rem;
}

.form-group-checkbox label {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    font-weight: normal;
}

.form-group-checkbox input[type="checkbox"] {
    width: auto;
}

/* Buttons */
.step-actions {
    margin-top: 2rem;
    display: flex;
    gap: 1rem;
    justify-content: flex-end;
}

.btn {
    padding: 0.6rem 1.5rem;
    border: none;
    border-radius: 4px;
    font-size: 0.95rem;
    font-weight: 500;
    cursor: pointer;
    transition: background 0.2s;
}

.btn:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-primary {
    background: #1976d2;
    color: #fff;
}

.btn-primary:hover:not(:disabled) {
    background: #1565c0;
}

.btn-outline {
    background: transparent;
    border: 1px solid #ccc;
    color: #555;
}

.btn-outline:hover {
    background: #f5f5f5;
}

.btn-secondary {
    background: #f5f5f5;
    border: 1px dashed #ccc;
    color: #555;
    margin-bottom: 1rem;
}

.btn-secondary:hover {
    background: #eeeeee;
}

.btn-danger {
    background: #e53935;
    color: #fff;
}

.btn-danger:hover {
    background: #c62828;
}

.btn-sm {
    padding: 0.3rem 0.8rem;
    font-size: 0.85rem;
}

.btn-link {
    background: none;
    border: none;
    color: #1976d2;
    cursor: pointer;
    font-size: 0.9rem;
    padding: 0;
    text-decoration: underline;
}

.btn-link:hover {
    color: #1565c0;
}

.btn-submit {
    padding: 0.75rem 2rem;
    font-size: 1rem;
}

/* Fieldsets */
fieldset {
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    padding: 1.25rem;
    margin-bottom: 1rem;
}

fieldset legend {
    font-weight: 600;
    font-size: 0.9rem;
    color: #555;
    padding: 0 0.5rem;
}

/* Character count */
.char-count {
    display: block;
    text-align: right;
    font-size: 0.8rem;
    color: #888;
    margin-top: 0.25rem;
}

.char-count.over-limit {
    color: #e53935;
    font-weight: 600;
}

/* Alerts */
.alert {
    padding: 0.75rem 1rem;
    border-radius: 4px;
    margin-bottom: 1rem;
}

.alert-danger {
    background: #ffebee;
    color: #c62828;
    border: 1px solid #ef9a9a;
}

.alert-success {
    background: #e8f5e9;
    color: #2e7d32;
    border: 1px solid #a5d6a7;
}

/* Review */
.review-section {
    border-bottom: 1px solid #eee;
    padding-bottom: 1rem;
    margin-bottom: 1rem;
}

.review-section:last-of-type {
    border-bottom: none;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.review-header h3 {
    margin: 0 0 0.5rem 0;
    font-size: 1.1rem;
}

.review-section dl {
    display: grid;
    grid-template-columns: 120px 1fr;
    gap: 0.25rem 1rem;
    margin: 0;
}

.review-section dt {
    font-weight: 500;
    color: #666;
}

.review-section dd {
    margin: 0;
}

.review-entry {
    margin-bottom: 0.75rem;
    padding-left: 0.5rem;
    border-left: 3px solid #e0e0e0;
}

.cover-letter-preview {
    white-space: pre-wrap;
    background: #fafafa;
    padding: 1rem;
    border-radius: 4px;
    border: 1px solid #eee;
}

.text-muted {
    color: #888;
    font-size: 0.85rem;
}

